/**
 * How long to wait for in-flight requests to drain on SIGTERM/SIGINT before
 * forcing exit. Keeps shutdown bounded even if a client connection hangs.
 */
export const SHUTDOWN_TIMEOUT_MS = 10_000;

/**
 * Build the HTTP/SSE transport's express app: `/mcp` (via
 * `StreamableHTTPServerTransport`), plus `/health` and `/ready`. Built from
 * the same `createServer(config)` used by the stdio transport — no change to
 * tool/resource registration. Separate from `startHttpServer` so a caller owns
 * the bind: tests listen on an ephemeral port, production on the configured one.
 */
export function createHttpApp(config: ServerConfig): Express {
  const host = config.host ?? 'localhost';
  const app = createMcpExpressApp({ host });
  app.use(requestId);
  app.use(requestLogging);

  registerHealthRoutes(app, config);
  registerMcpRoute(app, config);

  // Catch-all: unmatched routes (including OAuth discovery probes from
  // mcp-remote at /.well-known/oauth-*). Respond with the shared JSON error
  // shape without throwing — 4xx must not surface as type:error log lines.
  app.use((req: Request, res: Response, _next: NextFunction) => {
    res.status(404).json({
      error: 'NotFoundError',
      message: `Not found: ${req.method} ${req.path}`,
      requestId: req.requestId,
      timestamp: new Date().toISOString(),
    });
  });
  app.use(errorHandler);

  return app;
}

/**
 * Start the HTTP transport: build the app, bind it to `config.host`/`.port`,
 * and install the graceful-shutdown signal handlers. Returns the underlying
 * `http.Server` (mainly useful to tests that need to close it explicitly).
 */
export async function startHttpServer(config: ServerConfig): Promise<HttpServer> {
  const host = config.host ?? 'localhost';
  const port = config.port ?? 3000;
  const app = createHttpApp(config);

  const httpServer: HttpServer = await new Promise((resolvePromise, reject) => {
    const server = app.listen(port, host, () => resolvePromise(server));
    server.on('error', reject);
  });

  logInfo('Server connected and ready', { transport: 'http', host, port });
  installGracefulShutdown(httpServer);
  return httpServer;
}

function registerHealthRoutes(app: Express, config: ServerConfig): void {
  // Liveness: the process is up and serving requests. No dependency checks —
  // a liveness probe should only fail when the process itself is wedged.
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  // Readiness: schemas and the workspace resolve, the session HMAC key
  // directory is writable (start_session fails hard otherwise), and the corpus
  // holds at least one workflow — a listener whose corpus names nothing answers
  // every tool call with a miss, so readiness that ignored it would report a
  // server that cannot serve.
  // `checks.workspaceDir` is the configured worktree / workspace root
  // (`--workspace` / `WORKFLOW_WORKSPACE` / `WORKTREE_ROOT` / `--repo`);
  // the JSON key stays `workspaceDir` for existing HTTP consumers.
  // `engineeringDir` is included when split from workspace (repo binding).
  // `corpus` reports the tree this server resolves against and what the walk
  // found in it, and names the host tree behind it when a bind source was
  // passed in. Every container resolves definitions at the same mount point, so
  // `dir` alone says what a server reads and nothing about which corpus that
  // is; `hostDir` is what distinguishes two instances, and `pin` the commit
  // behind it, which outlives the worktree the path names.
  // `sessions` names the sessions standing on that bind. One instance serves
  // every session walking its corpus, and the bind moves for all of them at
  // once, so a bind about to move is read here for what the move displaces.
  app.get('/ready', async (_req, res) => {
    const engineeringDir = config.engineeringDir ?? config.workspaceDir;
    const sessionKeyWritable = await probeSessionKeyWritable();
    const corpus = describeCorpus(config.workflowDir, config.hostWorkflowsDir, config.corpusPin);
    const checks: Record<string, boolean> = {
      schemasDir: existsSync(config.schemasDir),
      workspaceDir: existsSync(config.workspaceDir),
      sessionKeyWritable,
      corpusServes: corpus.workflows > 0,
    };
    if (engineeringDir !== config.workspaceDir) {
      checks['engineeringDir'] = existsSync(engineeringDir);
